UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('why_asked', 'データ分析で最も陥りやすい誤りとして頻出で、共通の原因(交絡)の存在を見落として因果と決めつけやすいから。', 'viz', '<svg viewBox="0 0 340 148" xmlns="http://www.w3.org/2000/svg" font-family="sans-serif"><text x="170" y="18" fill="#e8eaf0" font-size="10.5" text-anchor="middle" font-weight="600">気温という共通の原因が、両方を押し上げる</text><text x="170" y="42" fill="#c9a04a" font-size="13" text-anchor="middle" font-weight="700">気温</text><line x1="158" y1="50" x2="92" y2="92" stroke="#c9a04a" stroke-width="1.5"/><polygon points="92,92 95.4,87.1 97.9,91.0" fill="#c9a04a"/><line x1="182" y1="50" x2="248" y2="92" stroke="#c9a04a" stroke-width="1.5"/><polygon points="248,92 242.1,91.0 244.6,87.1" fill="#c9a04a"/><text x="80" y="108" fill="#60a5fa" font-size="11" text-anchor="middle" font-weight="600">アイスの売上</text><text x="260" y="108" fill="#60a5fa" font-size="11" text-anchor="middle" font-weight="600">水難事故</text><line x1="105" y1="100" x2="235" y2="100" stroke="#2a2f3f" stroke-width="1.5" stroke-dasharray="3 3"/><text x="170" y="116" fill="#8892a4" font-size="9" text-anchor="middle">直接の原因ではない</text><text x="170" y="136" fill="#e8eaf0" font-size="10" text-anchor="middle">相関はあっても因果とは限らない</text></svg>') WHERE source_ref = 'g-kentei-b-q42' AND subject_id = (SELECT id FROM public.subjects WHERE slug = 'g-kentei-b');
